import java.io.InputStream;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskF solver = new TaskF();
        solver.solve(1, in, out);
        out.close();
    }
    static class TaskF {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int N = in.nextInt();
            int MOD = 1_000_000_007;
            // Use a single 3D array: dp[x][y][0] = dp1, dp[x][y][1] = dp2
            int[][][] dp = new int[N+1][N+1][2];

            for (int x = N; x >= 0; --x) {
                for (int y = N; y >= 0; --y) {
                    int d1 = 0, d2 = 0;
                    // calc d2
                    if (x+1 <= N) {
                        int m = Math.max(dp[x+1][y][0], dp[x+1][y][1]);
                        d2 += m;
                    }
                    d2 %= MOD;
                    if (y+1 <= Math.min(x, N)) {
                        int m = Math.max(dp[x][y+1][0], dp[x][y+1][1]);
                        d2 += m;
                    }
                    d2 %= MOD;

                    if (x+1 <= N) {
                        int m = Math.max(dp[x+1][y][0], dp[x+1][y][1]);
                        d1 = Math.max(d1, 1 + d2 - m + dp[x+1][y][1]);
                        d1 %= MOD;
                        if (d1 < 0) d1 += MOD;
                    }
                    if (y+1 <= Math.min(x, N)) {
                        int m = Math.max(dp[x][y+1][0], dp[x][y+1][1]);
                        d1 = Math.max(d1, 1 + d2 - m + dp[x][y+1][1]);
                        d1 %= MOD;
                        if (d1 < 0) d1 += MOD;
                    }
                    d1 %= MOD;
                    if (d1 < 0) d1 += MOD;
                    d2 %= MOD;
                    if (d2 < 0) d2 += MOD;

                    dp[x][y][0] = d1;
                    dp[x][y][1] = d2;
                }
            }

            int ans = Math.max(dp[0][0][0], dp[0][0][1]);

            out.print("" + ans);
            out.println();
        }
    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}
